<?php
namespace App\Console\Commands; use App\Services\Warehouse\Finance\WarehouseFinanceService; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB;
class WarehouseFinanceBackfillInvoicesCommand extends Command{protected $signature='warehouse:finance-backfill-invoices {--limit=500}';protected $description='Membentuk invoice idempotent untuk GR completed yang belum memiliki invoice';public function handle(WarehouseFinanceService $service):int{$user=DB::table('users')->orderBy('created_at')->first();if(!$user){$this->error('User actor tidak tersedia.');return self::FAILURE;}$ids=DB::table('wh_sales_goods_receipts as g')->leftJoin('wh_sales_invoices as i','i.goods_receipt_id','=','g.id')->where('g.status','completed')->whereNull('i.id')->limit((int)$this->option('limit'))->pluck('g.id');$ok=0;foreach($ids as $id){$service->generateInvoice($id,$user);$ok++;}$this->info("Invoice terbentuk: {$ok}");return self::SUCCESS;}}